<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$id=(int)($_GET['id']??0);if(!$pdo||$id<1){header('Location: audio.php');exit;}$s=$pdo->prepare('SELECT title,audio_url,cover_image FROM audio_tracks WHERE id=?');$s->execute([$id]);$a=$s->fetch();if(!$a){header('Location: audio.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach(['audio_url','cover_image'] as $field){$file=$a[$field]??'';$root=realpath(__DIR__.'/../uploads');$target=$file?realpath(__DIR__.'/../'.$file):false;if($root&&$target&&str_starts_with($target,$root.DIRECTORY_SEPARATOR)&&is_file($target))unlink($target);}log_admin_activity('audio_deleted','Audio ID: '.$id);$pdo->prepare('DELETE FROM audio_tracks WHERE id=?')->execute([$id]);header('Location: audio.php');exit;}?><!doctype html><html lang="en"><head><meta charset="utf-8"><title>Delete Audio</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="container"><section class="card"><h1>Delete audio?</h1><p><?=e($a['title'])?></p><p>This also removes stored media files.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><button>Delete permanently</button> <a href="audio.php">Cancel</a></form></section></main></body></html>
